#include <iostream>
#include <cstdint>
std::uint64_t factorial(unsigned n){return n<2?1:n*factorial(n-1);}
int main(){int n;if(!(std::cin>>n)||n<0||n>12){std::cout<<"limit\n";return 0;}std::uint64_t iterative=1;for(int i=2;i<=n;++i)iterative*=static_cast<unsigned>(i);auto result=factorial(static_cast<unsigned>(n));if(result!=iterative)return 2;std::cout<<result<<'\n';}

#include <iostream>
#include <vector>
#include <algorithm>
void merge_sort(std::vector<int>&a,std::size_t lo,std::size_t hi,int depth,int&maximum){maximum=std::max(maximum,depth);if(hi-lo<2)return;auto mid=lo+(hi-lo)/2;merge_sort(a,lo,mid,depth+1,maximum);merge_sort(a,mid,hi,depth+1,maximum);std::vector<int>tmp;auto i=lo,j=mid;while(i<mid&&j<hi){if(a[j]<a[i])tmp.push_back(a[j++]);else tmp.push_back(a[i++]);}while(i<mid)tmp.push_back(a[i++]);while(j<hi)tmp.push_back(a[j++]);std::copy(tmp.begin(),tmp.end(),a.begin()+static_cast<std::ptrdiff_t>(lo));}
int main(){int n;if(!(std::cin>>n)||n<0||n>128){std::cout<<"limit\n";return 0;}std::vector<int>a;for(int i=0;i<n;++i){int x;if(!(std::cin>>x))return 2;a.push_back(x);}auto expected=a;std::sort(expected.begin(),expected.end());int maximum=0;merge_sort(a,0,a.size(),1,maximum);if(a!=expected||maximum>8)return 3;std::cout<<"sorted "<<a.size()<<" bounded\n";}
